import os, sys, json, re, ast, time, uuid, copy
from pathlib import Path
from datetime import datetime, timezone
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
import aws_cli

REGION = 'us-west-2'
ACCOUNT = '000000000000'
PREFIX = 'stackd-enc-ex-' + uuid.uuid4().hex[:10]
DEST = Path('testdata/aws/stepfunctions/encryption_execution.json')
SOURCE = Path('/tmp/stackd_encryption_execution_probe.py')
BASE = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_PAGER='', AWS_MAX_ATTEMPTS='1')
ENV = {'default': BASE}
DATA = {'account':ACCOUNT,'region':REGION,'prefix':PREFIX,'caller_arn':None,'observations':[], 'actors':{},'notes':[], 'references':['https://docs.aws.amazon.com/step-functions/latest/dg/encryption-at-rest.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_StartExecution.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_StartSyncExecution.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_DescribeExecution.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_GetExecutionHistory.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_GetActivityTask.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_SendTaskSuccess.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_SendTaskFailure.html','https://docs.aws.amazon.com/step-functions/latest/apireference/API_SendTaskHeartbeat.html'],'source':'','cleanup':{}}
BLOCKS=[]
ROLES=[]
KEYS={}
MACHINES={}
ACTIVITIES={}
EXECUTIONS={}
TOKENS={}
START_MS=int(time.time()*1000)

def sanitize(value):
    if isinstance(value,dict):
        out={}
        for k,v in value.items():
            if k in ('AccessKeyId','SecretAccessKey','SessionToken','accessKeyId','Plaintext','CiphertextBlob'):
                out[k]='<REDACTED>'
            elif k=='taskToken' and isinstance(v,str) and v:
                if v not in TOKENS: TOKENS[v]='<TASK_TOKEN_%d>'%(len(TOKENS)+1)
                out[k]=TOKENS[v]
            else: out[k]=sanitize(v)
        return out
    if isinstance(value,list): return [sanitize(v) for v in value]
    return value

def save():
    DATA['source']=SOURCE.read_text()+'\n# Executed probe blocks follow.\n'+''.join('\n'+b+'\n' for b in BLOCKS)
    DEST.write_text(json.dumps(DATA,indent=2)+'\n')

def block(code):
    BLOCKS.append(code)
    try: exec(code,globals())
    finally: save()

def request(label,service,operation,params=None,actor='default',cleanup=False,timeout=45,filter_output=None,quiet=False):
    started=int(time.time()*1000)
    options=['--region',REGION,'--no-paginate','--cli-connect-timeout','8','--cli-read-timeout',str(timeout-5),'--debug']
    try:
        process=aws_cli.run(service,operation,params or {},ENV[actor],options=options,timeout=timeout)
        result=aws_cli.result(process,debug=True)
        if result['code']!='Success':
            matches=re.findall(r'Response body:\s*\n(b[\'\"].*)',process.stderr)
            for text in reversed(matches):
                try:
                    body=json.loads(ast.literal_eval(text))
                    if isinstance(body,dict): result['output']=body; break
                except (ValueError,SyntaxError,json.JSONDecodeError): pass
        headers=re.findall(r'Response headers: (\{[^\n]+\})',process.stderr)
        for text in reversed(headers):
            try:
                native_headers=ast.literal_eval(text)
                ids={k:v for k,v in native_headers.items() if k.lower() in ('x-amzn-requestid','x-amz-request-id','x-amzn-request-id')}
                if ids: result['request_ids']=ids; break
            except (ValueError,SyntaxError): pass
        if result['code']=='Success' and filter_output: result['output']=filter_output(result.get('output',{}))
    except aws_cli.CLITimeout:
        result={'code':'ProbeTimeout','output':{'timeoutSeconds':timeout,'note':'Bounded client timeout; not a native service outcome.'}}
    result.setdefault('output',{})
    observed={'label':label,'service':service,'operation':operation,'actor':actor,'region':REGION,'input':sanitize(params or {}),'request_started_ms':started,'request_finished_ms':int(time.time()*1000),'result':sanitize(result)}
    DATA['observations'].append(observed)
    if cleanup: DATA['cleanup'].setdefault('observation_labels',[]).append(label)
    save()
    if not quiet: print(label,result['code'],result.get('output',{}).get('status',''),flush=True)
    return result

def require(label,service,operation,params=None,actor='default'):
    result=request(label,service,operation,params,actor)
    if result['code']!='Success': raise RuntimeError(label+': '+result['code'])
    return result['output']

def role(name,statements,caller=False):
    rn=PREFIX+'-'+name
    principal={'AWS':DATA['caller_arn']} if caller else {'Service':'states.amazonaws.com'}
    trust={'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':principal,'Action':'sts:AssumeRole'}]}
    if not caller: trust['Statement'][0]['Condition']={'StringEquals':{'aws:SourceAccount':ACCOUNT}}
    out=require('setup-role-'+name,'iam','create-role',{'RoleName':rn,'AssumeRolePolicyDocument':json.dumps(trust),'Description':'Owned bounded Step Functions KMS native probe'})
    ROLES.append(rn)
    policy={'Version':'2012-10-17','Statement':statements}
    require('setup-policy-'+name,'iam','put-role-policy',{'RoleName':rn,'PolicyName':'owned','PolicyDocument':json.dumps(policy)})
    DATA['actors'][name]={'kind':'caller-assumed-role' if caller else 'state-machine-execution-role','role_name':rn,'role_arn':out['Role']['Arn'],'trust_policy':trust,'inline_policy':policy,'session_policy':None,'policy_immutable_during_probe':True}
    return out['Role']['Arn']

def assume(name):
    actor=DATA['actors'][name]
    params={'RoleArn':actor['role_arn'],'RoleSessionName':PREFIX+'-'+name,'DurationSeconds':3600}
    for n in range(4):
        out=request('setup-assume-'+name+'-'+str(n),'sts','assume-role',params)
        if out['code']=='Success': break
        time.sleep(4)
    if out['code']!='Success': raise RuntimeError('assume '+name)
    creds=out['output']['Credentials']
    ENV[name]=dict(BASE,AWS_ACCESS_KEY_ID=creds['AccessKeyId'],AWS_SECRET_ACCESS_KEY=creds['SecretAccessKey'],AWS_SESSION_TOKEN=creds['SessionToken'])
    ENV[name].pop('AWS_PROFILE',None)
    actor.update(assume_role_input=params,session_arn=out['output']['AssumedRoleUser']['Arn'],session_policy=None,session_tags=[],source_identity=None,external_id=None,mfa=None,duration_seconds=3600)
    require('identity-'+name,'sts','get-caller-identity',actor=name)

def enc(key): return {'type':'CUSTOMER_MANAGED_KMS_KEY','kmsKeyId':KEYS[key],'kmsDataKeyReusePeriodSeconds':60}

def machine(name,execution_role,kind='STANDARD',definition=None,key='machine'):
    if definition is None: definition={'StartAt':'Pass','States':{'Pass':{'Type':'Pass','Next':'Wait'},'Wait':{'Type':'Wait','Seconds':1,'End':True}}}
    params={'name':PREFIX+'-'+name,'roleArn':DATA['actors'][execution_role]['role_arn'],'type':kind,'definition':json.dumps(definition),'encryptionConfiguration':enc(key)}
    out=require('setup-machine-'+name,'stepfunctions','create-state-machine',params)
    MACHINES[name]=out['stateMachineArn']
    return MACHINES[name]

def start(name,machine_name,actor='default',sync=False,metadata=False):
    params={'stateMachineArn':MACHINES[machine_name],'name':name,'input':json.dumps({'probe':name,'synthetic':True})}
    if metadata: params['includedData']='METADATA_ONLY'
    out=request(name+'-start','stepfunctions','start-sync-execution' if sync else 'start-execution',params,actor)
    if out['code']=='Success' and 'executionArn' in out['output']:
        EXECUTIONS[name]={'arn':out['output']['executionArn'],'machine':machine_name,'express':sync or machine_name.startswith('express')}
    return out

def history(name,actor='default',data=True,label=None):
    return request(label or name+'-history','stepfunctions','get-execution-history',{'executionArn':EXECUTIONS[name]['arn'],'includeExecutionData':data,'maxResults':1000},actor)

def settle(name,limit=8):
    if name not in EXECUTIONS: return
    for n in range(limit):
        result=request(name+'-settle-'+str(n),'stepfunctions','describe-execution',{'executionArn':EXECUTIONS[name]['arn'],'includedData':'METADATA_ONLY'})
        if result['code']=='Success' and result['output'].get('status')!='RUNNING': break
        time.sleep(2)
    history(name)

def activity(name):
    out=require('setup-activity-'+name,'stepfunctions','create-activity',{'name':PREFIX+'-'+name,'encryptionConfiguration':enc('activity')})
    ACTIVITIES[name]=out['activityArn']
    return out['activityArn']

def task_definition(activity_name):
    return {'StartAt':'Work','TimeoutSeconds':240,'States':{'Work':{'Type':'Task','Resource':ACTIVITIES[activity_name],'TimeoutSeconds':220,'End':True}}}

def get_task(label,activity_name,actor):
    return request(label,'stepfunctions','get-activity-task',{'activityArn':ACTIVITIES[activity_name],'workerName':PREFIX+'-'+actor},actor,timeout=72)

def cloudtrail(label):
    def own(output):
        events=[]
        for event in output.get('Events',[]):
            raw=json.loads(event['CloudTrailEvent'])
            if PREFIX in json.dumps(raw) or any(k in json.dumps(raw) for k in KEYS.values()):
                events.append({'EventId':event['EventId'],'EventName':event['EventName'],'EventTime':event['EventTime'],'CloudTrailEvent':sanitize(raw)})
        return {'Events':events,'unrelated_events_omitted':len(output.get('Events',[]))-len(events),'NextToken':output.get('NextToken'),'filter':'Owned prefix/key ARNs only; credentials redacted.'}
    for key,arn in KEYS.items():
        request(label+'-'+key,'cloudtrail','lookup-events',{'LookupAttributes':[{'AttributeKey':'ResourceName','AttributeValue':arn.rsplit('/',1)[-1]}],'StartTime':datetime.fromtimestamp(START_MS/1000-30,timezone.utc).isoformat(),'MaxResults':50},filter_output=own)

def cleanup():
    for name,execution in EXECUTIONS.items():
        if execution['express']: continue
        out=request('cleanup-execution-status-'+name,'stepfunctions','describe-execution',{'executionArn':execution['arn'],'includedData':'METADATA_ONLY'},cleanup=True)
        if out['code']=='Success' and out['output'].get('status')=='RUNNING':
            request('cleanup-stop-'+name,'stepfunctions','stop-execution',{'executionArn':execution['arn']},cleanup=True)
            request('cleanup-stopped-status-'+name,'stepfunctions','describe-execution',{'executionArn':execution['arn'],'includedData':'METADATA_ONLY'},cleanup=True)
    for name,arn in MACHINES.items(): request('cleanup-machine-'+name,'stepfunctions','delete-state-machine',{'stateMachineArn':arn},cleanup=True)
    for name,arn in ACTIVITIES.items(): request('cleanup-activity-'+name,'stepfunctions','delete-activity',{'activityArn':arn},cleanup=True)
    for rn in ROLES:
        request('cleanup-policy-'+rn,'iam','delete-role-policy',{'RoleName':rn,'PolicyName':'owned'},cleanup=True)
        request('cleanup-role-'+rn,'iam','delete-role',{'RoleName':rn},cleanup=True)
    for name,arn in KEYS.items(): request('cleanup-key-'+name,'kms','schedule-key-deletion',{'KeyId':arn,'PendingWindowInDays':7},cleanup=True)
    for name,arn in ACTIVITIES.items(): request('verify-activity-'+name,'stepfunctions','describe-activity',{'activityArn':arn},cleanup=True)
    for rn in ROLES: request('verify-role-'+rn,'iam','get-role',{'RoleName':rn},cleanup=True)
    for name,arn in KEYS.items(): request('verify-key-'+name,'kms','describe-key',{'KeyId':arn},cleanup=True)
    remaining=dict(MACHINES)
    for attempt in range(6):
        for name,arn in list(remaining.items()):
            out=request('verify-machine-'+name+'-'+str(attempt),'stepfunctions','describe-state-machine',{'stateMachineArn':arn,'includedData':'METADATA_ONLY'},cleanup=True)
            if out['code']=='StateMachineDoesNotExist': remaining.pop(name)
        if not remaining: break
        time.sleep(5)
    DATA['cleanup']['machines_still_visible']=remaining
    DATA['cleanup']['kms_note']='Both CMKs scheduled for minimum seven-day deletion; PendingDeletion is retained resource state, not physical deletion.'
    DATA['cleanup']['execution_note']='All observed Standard executions terminal or stopped. AWS retains execution records; there is no DeleteExecution API. Express async runs contain only Pass and 1-second Wait; terminal status cannot be queried without logs.'
    save()

# Executed probe blocks follow.


identity=require('identity-default','sts','get-caller-identity')
if identity['Account']!=ACCOUNT: raise RuntimeError('Wrong account')
DATA['caller_arn']=identity['Arn']
DATA['actors']['default']={'kind':'ambient CLI principal','arn':identity['Arn'],'identity':identity,'session_policy':'Preexisting ambient principal; neither modified nor reconstructed. All nondefault test actors are owned immutable roles with explicit policies below.'}
key_policy={'Version':'2012-10-17','Statement':[{'Sid':'EnableOwnedAccountIAM','Effect':'Allow','Principal':{'AWS':'arn:aws:iam::'+ACCOUNT+':root'},'Action':'kms:*','Resource':'*'}]}
for name in ('machine','activity'):
    key=require('setup-key-'+name,'kms','create-key',{'Description':PREFIX+'-'+name,'KeyUsage':'ENCRYPT_DECRYPT','KeySpec':'SYMMETRIC_DEFAULT','Policy':json.dumps(key_policy),'Tags':[{'TagKey':'native-probe','TagValue':PREFIX}]})
    KEYS[name]=key['KeyMetadata']['Arn']
DATA['key_policy']=key_policy
machine_allow={'Effect':'Allow','Action':['kms:GenerateDataKey','kms:Decrypt'],'Resource':KEYS['machine'],'Condition':{'StringLike':{'kms:EncryptionContext:aws:states:stateMachineArn':'arn:aws:states:'+REGION+':'+ACCOUNT+':stateMachine:'+PREFIX+'-*'}}}
activity_allow={'Effect':'Allow','Action':['kms:GenerateDataKey','kms:Decrypt'],'Resource':KEYS['activity'],'Condition':{'StringLike':{'kms:EncryptionContext:aws:states:activityArn':'arn:aws:states:'+REGION+':'+ACCOUNT+':activity:'+PREFIX+'-*'}}}
role('exec-allow',[machine_allow,activity_allow])
for action,suffix in [('kms:GenerateDataKey','gen'),('kms:Decrypt','decrypt')]:
    role('exec-deny-'+suffix,[machine_allow,activity_allow,{'Effect':'Deny','Action':action,'Resource':KEYS['machine']}])
    role('activity-deny-'+suffix,[machine_allow,activity_allow,{'Effect':'Deny','Action':action,'Resource':KEYS['activity']}])
wrong=copy.deepcopy(activity_allow)
wrong['Condition']={'StringLike':{'kms:EncryptionContext:aws:states:stateMachineArn':'arn:aws:states:'+REGION+':'+ACCOUNT+':stateMachine:'+PREFIX+'-*'}}
role('activity-wrong-context',[machine_allow,wrong])
for name,keys in [('caller-allow',list(KEYS.values())),('caller-machine',[KEYS['machine']]),('caller-activity',[KEYS['activity']]),('caller-no-kms',[])]:
    statements=[{'Effect':'Allow','Action':['states:StartExecution','states:StartSyncExecution','states:DescribeExecution','states:GetExecutionHistory','states:GetActivityTask','states:SendTaskSuccess','states:SendTaskFailure','states:SendTaskHeartbeat','states:StopExecution'],'Resource':'*'}]
    if keys: statements.append({'Effect':'Allow','Action':'kms:Decrypt','Resource':keys})
    if not keys: statements.append({'Effect':'Deny','Action':'kms:*','Resource':'*'})
    role(name,statements,caller=True)
time.sleep(12)
for name in ('caller-allow','caller-machine','caller-activity','caller-no-kms'): assume(name)
for suffix in ('allow','deny-gen','deny-decrypt'):
    machine('standard-'+suffix,'exec-'+suffix)
    machine('express-'+suffix,'exec-'+suffix,kind='EXPRESS')
DATA['notes'].append('Each execution-role policy is installed once before any use and never mutated. Each caller authority has a distinct immutable role and STS identity; no restrictive session policy, tags, source identity, external ID, or MFA was supplied. All resource payloads are synthetic. Task tokens are deterministic redaction placeholders tied across observations; AWS data keys are never requested directly.')


for suffix in ('allow','deny-gen','deny-decrypt'):
    for repeat in ('cold','repeat'):
        name='standard-'+suffix+'-'+repeat
        start(name,'standard-'+suffix,actor='caller-no-kms')
        settle(name)
for suffix in ('allow','deny-gen','deny-decrypt'):
    start('express-'+suffix+'-sync','express-'+suffix,actor='caller-allow',sync=True)
    start('express-'+suffix+'-sync-repeat','express-'+suffix,actor='caller-allow',sync=True)
    start('express-'+suffix+'-async','express-'+suffix,actor='caller-no-kms')
start('express-allow-caller-no-kms','express-allow',actor='caller-no-kms',sync=True)
start('express-allow-caller-no-kms-metadata','express-allow',actor='caller-no-kms',sync=True,metadata=True)
retained=EXECUTIONS['standard-allow-cold']['arn']
for actor in ('caller-no-kms','caller-allow'):
    for included in ('ALL_DATA','METADATA_ONLY'):
        request('retained-enabled-'+actor+'-'+included,'stepfunctions','describe-execution',{'executionArn':retained,'includedData':included},actor)
    for data in (True,False): history('standard-allow-cold',actor,data,'retained-enabled-history-'+actor+'-'+str(data))
via=copy.deepcopy(machine_allow)
via['Condition']['StringEquals']={'kms:ViaService':'states.'+REGION+'.amazonaws.com'}
role('exec-viaservice',[via])
role('caller-viaservice',[{'Effect':'Allow','Action':['states:DescribeExecution','states:GetExecutionHistory','states:StartSyncExecution'],'Resource':'*'},{'Effect':'Allow','Action':'kms:Decrypt','Resource':KEYS['machine'],'Condition':{'StringEquals':{'kms:ViaService':'states.'+REGION+'.amazonaws.com'}}}],caller=True)
time.sleep(10)
assume('caller-viaservice')
machine('standard-viaservice','exec-viaservice')
start('standard-viaservice-cold','standard-viaservice',actor='caller-no-kms')
settle('standard-viaservice-cold')
request('retained-caller-viaservice','stepfunctions','describe-execution',{'executionArn':retained,'includedData':'ALL_DATA'},'caller-viaservice')
start('express-caller-viaservice','express-allow',actor='caller-viaservice',sync=True)
cloudtrail('cloudtrail-initial')


role('exec-sync-no-kms',[{'Effect':'Deny','Action':'kms:*','Resource':list(KEYS.values())}])
time.sleep(8)
machine('express-cold-no-kms','exec-sync-no-kms',kind='EXPRESS')
start('express-fresh-both-no-kms','express-cold-no-kms',actor='caller-no-kms',sync=True)
start('express-fresh-both-no-kms-explicit-all','express-cold-no-kms',actor='caller-no-kms',sync=True)
for name in ('delivery','failure-filled','failure-null','disabled-success','disabled-filled','disabled-null'):
    activity(name)
    machine('activity-'+name,'exec-allow',definition=task_definition(name))
for suffix in ('deny-gen','deny-decrypt','wrong-context'):
    name='authority-'+suffix
    activity(name)
    machine('activity-'+name,'activity-'+suffix,definition=task_definition(name))
    start('activity-'+name,'activity-'+name,actor='caller-no-kms')
    settle('activity-'+name,limit=5)


# After probe kernel interruption, owned resources were reconstructed from observations,
# and each caller session was re-assumed with unchanged policies.
for name in ('caller-allow','caller-machine','caller-activity','caller-no-kms','caller-viaservice'): assume(name)

start('activity-delivery','activity-delivery',actor='caller-no-kms')
time.sleep(2)
get_task('delivery-caller-no-kms','delivery','caller-no-kms')
get_task('delivery-caller-machine-only','delivery','caller-machine')
delivery=get_task('delivery-caller-activity-only','delivery','caller-activity')
if delivery['code']=='Success' and delivery['output'].get('taskToken'):
    token=delivery['output']['taskToken']
    request('delivery-heartbeat-caller-no-kms','stepfunctions','send-task-heartbeat',{'taskToken':token},'caller-no-kms')
    request('delivery-success-caller-no-kms','stepfunctions','send-task-success',{'taskToken':token,'output':json.dumps({'synthetic':'worker-success'})},'caller-no-kms')
    settle('activity-delivery')


for name in ('failure-filled','failure-null'):
    start('activity-'+name,'activity-'+name,actor='caller-no-kms')
    task=get_task(name+'-get',name,'caller-activity')
    if task['code']=='Success' and task['output'].get('taskToken'):
        params={'taskToken':task['output']['taskToken']}
        if name=='failure-filled': params.update(error='SyntheticWorkerError',cause='Synthetic callback cause')
        request(name+'-callback-caller-no-kms','stepfunctions','send-task-failure',params,'caller-no-kms')
        settle('activity-'+name)
cloudtrail('cloudtrail-activity')


start('activity-deny-decrypt-worker','activity-authority-deny-decrypt',actor='caller-no-kms')
task=get_task('activity-deny-decrypt-worker-get','authority-deny-decrypt','caller-activity')
if task['code']=='Success' and task['output'].get('taskToken'):
    request('activity-deny-decrypt-worker-success','stepfunctions','send-task-success',{'taskToken':task['output']['taskToken'],'output':'{"synthetic":"activity-decrypt-denied-execution-role"}'},'caller-no-kms')
settle('activity-deny-decrypt-worker',limit=3)
# Fresh Express machine: caller identity versus execution-role denial in isolation.
machine('express-cold-caller-denied','exec-allow',kind='EXPRESS')
start('express-cold-caller-denied','express-cold-caller-denied',actor='caller-no-kms',sync=True)
machine('express-cold-exec-denied','exec-sync-no-kms',kind='EXPRESS')
start('express-cold-exec-denied','express-cold-exec-denied',actor='caller-allow',sync=True)


# Resolve the two queued tasks by returned synthetic input, not request order.
task=get_task('activity-deny-decrypt-second-get','authority-deny-decrypt','caller-activity')
if task['code']=='Success' and task['output'].get('taskToken'):
    request('activity-deny-decrypt-second-success','stepfunctions','send-task-success',{'taskToken':task['output']['taskToken'],'output':'{"synthetic":"second-activity-decrypt-denied"}'},'caller-no-kms')
settle('activity-authority-deny-decrypt',limit=2)
settle('activity-deny-decrypt-worker',limit=2)
# Prepare multiple live tokens, then disable only the owned machine key.
DISABLED_TASKS={}
for name in ('disabled-success','disabled-filled','disabled-null'):
    start('activity-'+name,'activity-'+name,actor='caller-no-kms')
    task=get_task(name+'-get',name,'caller-activity')
    if task['code']=='Success' and task['output'].get('taskToken'): DISABLED_TASKS[name]=task['output']['taskToken']
machine('standard-disable-wait','exec-allow',definition={'StartAt':'Wait','States':{'Wait':{'Type':'Wait','Seconds':85,'Next':'Pass'},'Pass':{'Type':'Pass','End':True}}})
start('standard-disable-wait','standard-disable-wait',actor='caller-no-kms')
machine('standard-disable-cold','exec-allow')
machine('express-disable-cold','exec-allow',kind='EXPRESS')
start('standard-before-disable-warm','standard-allow',actor='caller-no-kms')
settle('standard-before-disable-warm')
require('disable-machine-key','kms','disable-key',{'KeyId':KEYS['machine']})
DISABLED_AT=time.time()
require('verify-machine-key-disabled','kms','describe-key',{'KeyId':KEYS['machine']})
start('standard-disabled-warm','standard-allow',actor='caller-no-kms')
start('standard-disabled-cold','standard-disable-cold',actor='caller-no-kms')
start('express-disabled-cold','express-disable-cold',actor='caller-allow',sync=True)
request('disabled-heartbeat-caller-no-kms','stepfunctions','send-task-heartbeat',{'taskToken':DISABLED_TASKS['disabled-success']},'caller-no-kms')


retained=EXECUTIONS['standard-allow-cold']['arn']
for actor in ('caller-allow','caller-no-kms'):
    for included in ('ALL_DATA','METADATA_ONLY'):
        request('retained-disabled-'+actor+'-'+included,'stepfunctions','describe-execution',{'executionArn':retained,'includedData':included},actor)
    for data in (True,False): history('standard-allow-cold',actor,data,'retained-disabled-history-'+actor+'-'+str(data))
# ResourceName may index only key creation under bare key IDs; collect ARN-indexed records too.
for key,arn in KEYS.items():
    request('cloudtrail-arn-'+key,'cloudtrail','lookup-events',{'LookupAttributes':[{'AttributeKey':'ResourceName','AttributeValue':arn}],'StartTime':datetime.fromtimestamp(START_MS/1000-30,timezone.utc).isoformat(),'MaxResults':50},filter_output=lambda out: {'Events':[dict(e,CloudTrailEvent=sanitize(json.loads(e['CloudTrailEvent']))) for e in out.get('Events',[])],'NextToken':out.get('NextToken')})


last=next(o for o in reversed(DATA['observations']) if o['label']=='cloudtrail-arn-machine')
next_token=last['result']['output'].get('NextToken')
if next_token:
    request('cloudtrail-arn-machine-page2','cloudtrail','lookup-events',{'LookupAttributes':[{'AttributeKey':'ResourceName','AttributeValue':KEYS['machine']}],'StartTime':datetime.fromtimestamp(START_MS/1000-30,timezone.utc).isoformat(),'MaxResults':50,'NextToken':next_token},filter_output=lambda out: {'Events':[dict(e,CloudTrailEvent=sanitize(json.loads(e['CloudTrailEvent']))) for e in out.get('Events',[])],'NextToken':out.get('NextToken')})
# This bounded pause reaches beyond configured 60-second data-key reuse, not a cache timing guarantee.
